String aName=seedName+'Aster',bName=seedName+'Birch',cName=seedName+'Cedar';
Account a=new Account(Name=aName,Industry='Technology');
Account b=new Account(Name=bName,Industry='Retail');
Account c=new Account(Name=cName,Industry='Technology');
insert new List<Account>{a,b,c};
Contact ca=new Contact(LastName='SJ-Aster-1',AccountId=a.Id);
Contact cb=new Contact(LastName='SJ-Birch-1',AccountId=b.Id);
Contact cc=new Contact(LastName='SJ-Aster-2',AccountId=a.Id);
Contact loose=new Contact(LastName='SJ-Unlinked');
insert new List<Contact>{ca,cb,cc,loose};
Set<Id> ids=new Set<Id>{a.Id,b.Id};
Set<Id> accountScope=new Set<Id>{a.Id,b.Id,c.Id};
Set<Id> contactScope=new Set<Id>{ca.Id,cb.Id,cc.Id,loose.Id};
Integer l=1,o=1;
v.put('phase','query');List<SObject> selected=Database.query('SELECT Id,Name FROM Account WHERE Id IN (SELECT AccountId FROM Contact WHERE Id IN :contactScope ) AND Name = :aName');Integer outOfScope=0;List<String> keys=new List<String>();List<String> children=new List<String>();for(SObject item:selected){if(!accountScope.contains(item.Id)){outOfScope++;continue;}String key=String.valueOf(item.get('Name'));if(item.Id==a.Id){key='SJ-Aster';}else if(item.Id==b.Id){key='SJ-Birch';}else if(item.Id==c.Id){key='SJ-Cedar';}keys.add(key);}keys.sort();children.sort();v.put('rows',selected.size());v.put('keys',keys);v.put('outOfScope',outOfScope);}catch(Exception e){v.put('exceptionType',e.getTypeName());v.put('exceptionMessage',e.getMessage());}System.assert(false,'C157_RESULT|C157SJ_031|'+JSON.serialize(v));

